// T0D-15 "golden widget tests" (06 plan). Baselines live in test/goldens/ and are generated by the WRITER with
// `flutter test --update-goldens test/golden_widgets_test.dart` once the widgets exist; the tester cannot produce them
// without the implementation. Until then these fail on the missing LimsTheme/widgets (and, after, on missing baselines).
// Fonts: tests use the bundled Noto faces loaded via the package assets so pixels do not depend on the host OS.
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:lims_ui/lims_ui.dart';

import '_helpers.dart';

void main() {
  testWidgets('golden: status chips, every tone, incl. Devanagari label', (tester) async {
    await tester.binding.setSurfaceSize(const Size(360, 420));
    addTearDown(() => tester.binding.setSurfaceSize(null));
    await tester.pumpWidget(host(const Padding(
      padding: EdgeInsets.all(16),
      child: Wrap(spacing: 8, runSpacing: 8, children: [
        LimsStatusChip(kind: 'specimen', status: 'ordered'),
        LimsStatusChip(kind: 'specimen', status: 'collected'),
        LimsStatusChip(kind: 'specimen', status: 'resulted'),
        LimsStatusChip(kind: 'specimen', status: 'approved'),
        LimsStatusChip(kind: 'specimen', status: 'rejected'),
        LimsFlagBadge(flag: 'HH'),
        LimsStatusChip(kind: 'generic', status: 'x', tone: 'info', label: 'नमूना प्राप्त भयो'),
      ]),
    )));
    await expectLater(find.byType(Scaffold), matchesGoldenFile('goldens/status_chips.png'));
  });

  testWidgets('golden: CR-C16-016 widgets column (otp, code, timeline, segmented)', (tester) async {
    await tester.binding.setSurfaceSize(const Size(360, 720));
    addTearDown(() => tester.binding.setSurfaceSize(null));
    await tester.pumpWidget(host(Padding(
      padding: const EdgeInsets.all(16),
      child: Column(children: [
        LimsOtpField(length: 6, onCompleted: (_) {}),
        LimsCodeField(label: 'Code', groupSize: 5, groups: 2, alphabet: '0123456789ABCDEFGHJKMNPQRSTVWXYZ', onChanged: (_) {}),
        const LimsStageTimeline(steps: [
          (label: 'Registered', state: LimsStepState.done),
          (label: 'In the lab', state: LimsStepState.current),
          (label: 'Report ready', state: LimsStepState.todo),
        ]),
        LimsSegmentedControl<String>(options: const [(value: 'self', label: 'Myself'), (value: 'child', label: 'My child')], value: 'self', onChanged: (_) {}),
      ]),
    )));
    await expectLater(find.byType(Scaffold), matchesGoldenFile('goldens/cr16_widgets.png'));
  });
}
